mapper.select:
SELECT name, cnname, tags, difficulty, 0 AS accepted
FROM problem

ORDER BY ${order}
LIMIT #{start}, #{limit}

SELECT public > 0 AS publicProblem, showsolution > 0 AS showSolution, caseAmount
FROM problem
WHERE name = #{name}

mapper.update:
UPDATE problem
SET caseAmount = caseAmount + 1
WHERE name = #{name}

